import React, { useState } from "react";
import "./style.css";
import { Helmet, HelmetProvider } from "react-helmet-async";
import { Container, Row, Col } from "react-bootstrap";
import { Link, useParams, Navigate } from "react-router-dom";
import { meta } from "../../content_option";
import { useLanguage } from "../../i18n/LanguageContext";
import { portfolioProjects } from "../../data/portfolioData";

export const PortfolioDetail = () => {
  const { id } = useParams();
  const { t, language } = useLanguage();
  const [copySuccess, setCopySuccess] = useState(false);

  const projectId = parseInt(id, 10);
  if (isNaN(projectId)) return <Navigate to="/portfolio" replace />;

  const projects = portfolioProjects[language] || portfolioProjects.en;
  const project = projects.find((p) => p.id === projectId);
  if (!project) return <Navigate to="/portfolio" replace />;

  // Related projects (same category, exclude current)
  const relatedProjects = projects
    .filter((p) => p.category === project.category && p.id !== project.id)
    .slice(0, 3);

  // Category label from translations
  const categoryKey = `portfolioDetail.categories.${project.category}`;
  const categoryLabel = t(categoryKey) !== categoryKey
    ? t(categoryKey)
    : project.category.toUpperCase();

  // Social sharing
  const pageUrl = encodeURIComponent(window.location.href);
  const projectTitle = encodeURIComponent(project.title);
  const shareUrls = {
    twitter: `https://twitter.com/intent/tweet?url=${pageUrl}&text=${projectTitle}`,
    linkedin: `https://www.linkedin.com/sharing/share-offsite/?url=${pageUrl}`,
    whatsapp: `https://api.whatsapp.com/send?text=${projectTitle}%20${pageUrl}`,
    facebook: `https://www.facebook.com/sharer/sharer.php?u=${pageUrl}`,
  };
  const handleShare = (platform) => {
    window.open(shareUrls[platform], "_blank", "noopener,noreferrer,width=600,height=500");
  };
  const handleCopyLink = async () => {
    try {
      await navigator.clipboard.writeText(window.location.href);
    } catch {
      const el = document.createElement("input");
      el.value = window.location.href;
      el.style.position = "fixed";
      el.style.left = "-9999px";
      document.body.appendChild(el);
      el.select();
      document.execCommand("copy");
      document.body.removeChild(el);
    }
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2500);
  };

  // JSON-LD schema
  const schema = {
    "@context": "https://schema.org",
    "@type": "CreativeWork",
    name: project.title,
    description: project.description,
    image: project.image,
    creator: { "@type": "Organization", name: "Tyber.io", url: "https://tyber.io" },
    keywords: project.tags.join(", "),
    url: window.location.href,
    inLanguage: language === "pt" ? "pt-BR" : "en",
  };

  return (
    <HelmetProvider>
      <section className="portfoliodetail-page">
        <Helmet>
          <html lang={language === 'pt' ? 'pt-BR' : 'en'} />
          <title>{project.title} | {meta.title}</title>
          <meta name="description" content={project.description} />
          <meta name="keywords" content={project.tags.join(", ")} />
          <link rel="canonical" href={window.location.href} />

          {/* Open Graph */}
          <meta property="og:type" content="website" />
          <meta property="og:title" content={project.title} />
          <meta property="og:description" content={project.description} />
          <meta property="og:image" content={project.image} />
          <meta property="og:url" content={window.location.href} />
          <meta property="og:site_name" content="Tyber.io" />

          {/* Twitter Card */}
          <meta name="twitter:card" content="summary_large_image" />
          <meta name="twitter:title" content={project.title} />
          <meta name="twitter:description" content={project.description} />
          <meta name="twitter:image" content={project.image} />
          <meta name="twitter:site" content="@tyber_io" />

          {/* JSON-LD */}
          <script type="application/ld+json">{JSON.stringify(schema)}</script>
        </Helmet>

        {/* Back link */}
        <Container className="portfoliodetail-back">
          <Link to="/portfolio" className="back-link">
            <span className="back-link__arrow">←</span>
            {t("portfolioDetail.backTo")}
          </Link>
        </Container>

        {/* Hero */}
        <div className="portfoliodetail-hero">
          <Container>
            <div className="portfoliodetail-hero__meta">
              <span className="portfoliodetail-hero__category">{categoryLabel}</span>
              <span className="meta-dot">·</span>
              <span>{t("portfolioDetail.client")}: <strong>{project.client}</strong></span>
              <span className="meta-dot">·</span>
              <span>{t("portfolioDetail.duration")}: <strong>{project.duration}</strong></span>
            </div>
            <h1 className="portfoliodetail-hero__title">{project.title}</h1>
            <div className="portfoliodetail-hero__tags">
              {project.tags.map((tag, i) => (
                <span key={i} className="hero-tag">{tag}</span>
              ))}
            </div>
          </Container>
        </div>

        {/* Featured image */}
        <Container className="portfoliodetail-image-wrap">
          <div className="portfoliodetail-featured-image">
            <img src={project.image} alt={project.title} loading="eager" />
          </div>
        </Container>

        {/* Body */}
        <Container className="portfoliodetail-body">
          <Row>
            <Col lg={8}>
              {/* Description */}
              <div className="project-description">
                <p>{project.description}</p>
              </div>

              {/* Key Results */}
              <div className="project-metrics">
                <h2 className="project-metrics__title">{t("portfolioDetail.keyResults")}</h2>
                <div className="metrics-grid">
                  {project.metrics.map((metric, i) => (
                    <div key={i} className="metric-card">
                      <div className="metric-card__value gradient-text">{metric.value}</div>
                      <div className="metric-card__label">{metric.label}</div>
                    </div>
                  ))}
                </div>
              </div>

              {/* Social sharing */}
              <div className="post-share">
                <h4 className="post-share__title">{t("portfolioDetail.shareTitle")}</h4>
                <div className="post-share__buttons">
                  <button className="share-btn share-btn--twitter" onClick={() => handleShare("twitter")} aria-label={t("portfolioDetail.shareTwitter")}>
                    <span className="share-btn__icon">𝕏</span>
                    <span className="share-btn__label">{t("portfolioDetail.shareTwitter")}</span>
                  </button>
                  <button className="share-btn share-btn--linkedin" onClick={() => handleShare("linkedin")} aria-label={t("portfolioDetail.shareLinkedin")}>
                    <span className="share-btn__icon">in</span>
                    <span className="share-btn__label">{t("portfolioDetail.shareLinkedin")}</span>
                  </button>
                  <button className="share-btn share-btn--whatsapp" onClick={() => handleShare("whatsapp")} aria-label={t("portfolioDetail.shareWhatsapp")}>
                    <span className="share-btn__icon">W</span>
                    <span className="share-btn__label">{t("portfolioDetail.shareWhatsapp")}</span>
                  </button>
                  <button className="share-btn share-btn--facebook" onClick={() => handleShare("facebook")} aria-label={t("portfolioDetail.shareFacebook")}>
                    <span className="share-btn__icon">f</span>
                    <span className="share-btn__label">{t("portfolioDetail.shareFacebook")}</span>
                  </button>
                  <button
                    className={`share-btn share-btn--copy${copySuccess ? " copied" : ""}`}
                    onClick={handleCopyLink}
                    aria-label={t("portfolioDetail.copyLink")}
                  >
                    <span className="share-btn__icon">⎘</span>
                    <span className="share-btn__label">
                      {copySuccess ? t("portfolioDetail.linkCopied") : t("portfolioDetail.copyLink")}
                    </span>
                  </button>
                </div>
              </div>
            </Col>

            {/* Sidebar */}
            <Col lg={4}>
              <aside className="project-sidebar">
                {/* Technologies */}
                <div className="sidebar-card">
                  <h4 className="sidebar-card__title">{t("portfolioDetail.technologies")}</h4>
                  <div className="tech-tags">
                    {project.technologies.map((tech, i) => (
                      <span key={i} className="tech-tag">{tech}</span>
                    ))}
                  </div>
                </div>

                {/* Project metadata */}
                <div className="sidebar-card">
                  <div className="project-meta-item">
                    <span className="project-meta-item__label">{t("portfolioDetail.client")}</span>
                    <span className="project-meta-item__value">{project.client}</span>
                  </div>
                  <div className="project-meta-item">
                    <span className="project-meta-item__label">{t("portfolioDetail.duration")}</span>
                    <span className="project-meta-item__value">{project.duration}</span>
                  </div>
                  <div className="project-meta-item">
                    <span className="project-meta-item__label">{t("portfolioDetail.category")}</span>
                    <span className="project-meta-item__value">{categoryLabel}</span>
                  </div>
                </div>

                {/* Live project CTA — only when real link exists */}
                {project.link && project.link !== "#" && (
                  <a
                    href={project.link}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="project-cta-btn"
                  >
                    {t("portfolioDetail.viewProject")}
                    <span className="project-cta-btn__arrow">→</span>
                  </a>
                )}
              </aside>
            </Col>
          </Row>
        </Container>

        {/* Related Projects */}
        {relatedProjects.length > 0 && (
          <Container className="portfoliodetail-related">
            <h2 className="related-title">{t("portfolioDetail.relatedTitle")}</h2>
            <Row>
              {relatedProjects.map((relProj) => (
                <Col lg={4} md={6} key={relProj.id} className="mb-4">
                  <div className="portfolio-card">
                    <div className="portfolio-card__image">
                      <img src={relProj.image} alt={relProj.title} loading="lazy" />
                      <div className="portfolio-card__overlay">
                        <div className="portfolio-card__tags">
                          {relProj.tags.map((tag, idx) => (
                            <span key={idx} className="tag">{tag}</span>
                          ))}
                        </div>
                        <Link to={`/portfolio/${relProj.id}`} className="portfolio-card__cta">
                          {t("portfolio.cta")} <span className="arrow">→</span>
                        </Link>
                      </div>
                    </div>
                    <div className="portfolio-card__content">
                      <h3 className="portfolio-card__title">{relProj.title}</h3>
                      <p className="portfolio-card__client">{relProj.client}</p>
                      <p className="portfolio-card__description">{relProj.description}</p>
                    </div>
                  </div>
                </Col>
              ))}
            </Row>
          </Container>
        )}
      </section>
    </HelmetProvider>
  );
};
